function transport_test_assert(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function transport_test_request(string $url,string $session,?array $post=null):array{$c=curl_init($url);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_HEADER=>true,CURLOPT_COOKIE=>'aviculture_session='.$session,CURLOPT_TIMEOUT=>8]);if($post!==null){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,http_build_query($post));}$raw=curl_exec($c);if(!is_string($raw))throw new RuntimeException(curl_error($c));$status=(int)curl_getinfo($c,CURLINFO_RESPONSE_CODE);$hs=(int)curl_getinfo($c,CURLINFO_HEADER_SIZE);curl_close($c);return[$status,substr($raw,0,$hs),substr($raw,$hs)];}
function transport_test_flatten_fields(array $fields,string $prefix=''):array{$flat=[];foreach($fields as $key=>$value){$name=$prefix===''?(string)$key:$prefix.'['.$key.']';if(is_array($value))$flat+=transport_test_flatten_fields($value,$name);else $flat[$name]=is_scalar($value)?(string)$value:'';}return$flat;}
